#include <SymbolicRegression.hpp>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <fstream>
#include <chrono>
#include <cmath>
#include <bit>
#include <ctime>

namespace {
std::string quote(std::string_view s){std::string r="\"";for(char c:s){if(c=='\"')r+="\"\"";else r+=c;}return r+'\"';}
std::vector<RegressionRow> rows(bool held){std::vector<RegressionRow> r;for(int i=0;i<(held?12:24);++i){const double x=held?.25+.2*i:.2+.1*i;r.push_back({{x},3.5*std::pow(x,1.7)});}return r;}
}
int main(int argc,char**argv){try{if(argc!=2)throw std::invalid_argument("usage: genetik_s1_evolutionary_comparison OUTPUT.tsv");std::ofstream out(argv[1]);if(!out)throw std::runtime_error("cannot open output");out<<"seed\tmethod\ttrain_mse\theldout_rmse\tnodes\tdepth\tconstant_count\tconstant_bits\texpression\tcandidate_evaluations\tobjective_attempts\tfit_attempts\tfit_rows\tfit_math_ops\tLM_objectives\tLM_jacobians\tLM_forwards\tLM_derivatives\tLM_model_ops\tLM_linear_algebra_ops\tLM_solves\taccepted\trejected\titerations_committed\tinvalid_losses\twall_seconds\tcpu_seconds\n"<<std::setprecision(17);
    constexpr std::array<std::uint32_t,2> seeds{701,709};for(auto seed:seeds)for(auto method:{ConstantFitMethod::Coordinate,ConstantFitMethod::LevenbergMarquardt}){auto train=rows(false),held=rows(true);auto problem=RegressionProblem::create(train,{127,8,8});auto diagnostics=std::make_shared<RefinementDiagnostics>(128);SymbolicRegressionConfig config;config.population=10;config.elites=1;config.maxGenerationAttempts=4;config.maxEvaluations=50;config.maxTrainingLossAttempts=20000;config.crossoverRate=.8f;config.mutationRate=.4f;config.grammar.operators={ExpressionKind::Add,ExpressionKind::Subtract,ExpressionKind::Multiply,ExpressionKind::Pow,ExpressionKind::Log,ExpressionKind::Exp};config.grammar.constants={-2,-1,0,1,2};config.grammar.exponents={1,2,3};config.grammar.realExponents={.5,1.5,2};config.grammar.powerExponentsAreConstants=true;config.grammar.continuousProbability=.4;config.grammar.continuousLower=-4;config.grammar.continuousUpper=4;config.grammar.initialMaxDepth=4;config.grammar.mutationMaxDepth=3;config.fitting=ConstantFitConfig{};config.fitting->method=method;config.fitting->maxLossAttempts=12;config.fitting->maxSweeps=8;config.fitting->maxProposals=64;config.fitting->initialStep=.4;config.fitting->minimumStep=1e-8;config.fitting->levenbergMarquardt.maxIterations=8;config.fitting->levenbergMarquardt.maxObjectiveEvaluations=12;config.fitting->levenbergMarquardt.maxJacobianEvaluations=8;config.fitting->levenbergMarquardt.maxMathematicalOperations=200000;config.diagnostics=diagnostics;RandomContext random(seed);const auto begin=std::chrono::steady_clock::now();const auto cpuBegin=std::clock();auto result=symbolicRegression(problem,config,random);const double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();const double cpuSeconds=static_cast<double>(std::clock()-cpuBegin)/CLOCKS_PER_SEC;if(!result.best)throw std::runtime_error("frozen regression comparison produced no valid best candidate");auto assessment=RegressionProblem::create(held,{127,8,8})->measure(result.best->expression());const auto nodes=result.best->expression().nodeCount();const auto depth=result.best->expression().depth();std::size_t constantCount=0;for(const auto&node:result.best->expression().nodes())if(node.kind()==ExpressionKind::Constant)++constantCount;const auto constantBits=constantCount*64;const auto&w=result.trainingWork;const auto&lm=result.optimizerWork;double heldRmse=assessment.loss.state()==FitnessState::Valid?std::sqrt(assessment.loss.score()):std::numeric_limits<double>::infinity();out<<seed<<'\t'<<(method==ConstantFitMethod::Coordinate?"coordinate":"levenberg-marquardt")<<'\t'<<result.best->fitness()<<'\t'<<heldRmse<<'\t'<<nodes<<'\t'<<depth<<'\t'<<constantCount<<'\t'<<constantBits<<'\t'<<quote(result.best->text())<<'\t'<<result.candidateEvaluations<<'\t'<<w.lossAttempts<<'\t'<<w.fittingLossAttempts<<'\t'<<w.rowAttempts<<'\t'<<result.supplementalWork.mathematicalOperations<<'\t'<<lm.objectiveEvaluations<<'\t'<<lm.jacobianEvaluations<<'\t'<<lm.forwardEvaluations<<'\t'<<lm.derivativeEvaluations<<'\t'<<lm.mathematicalOperations<<'\t'<<lm.linearAlgebraOperations<<'\t'<<lm.linearSolves<<'\t'<<lm.acceptedSteps<<'\t'<<lm.rejectedSteps<<'\t'<<result.publishedGenerations<<'\t'<<w.invalidLosses<<'\t'<<seconds<<'\t'<<cpuSeconds<<'\n';}
    std::cout<<"frozen evolutionary comparison written: "<<argv[1]<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
